def transform(grid):
    # Replace the colored 3-shaped occlusion with background from rotational symmetry.
    n=len(grid); m=len(grid[0])
    out=[row[:] for row in grid]
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 3:
                out[r][c] = grid[n-1-r][m-1-c]
    return out
